'use client';import{useEffect,useState}from'react';import Link from'next/link';export default function CookieNotice(){const[show,setShow]=useState(false);useEffect(()=>setShow(!localStorage.getItem('ps-cookie-choice')),[]);const pick=(v:string)=>{localStorage.setItem('ps-cookie-choice',v);setShow(false)};if(!show)return null;return <div className="cookie"><div><b>Privacy choices</b><p>Essential browser storage keeps saved prompts and preferences. Optional analytics and advertising require consent when added.</p></div><Link href="/privacy-policy">Privacy policy</Link><button onClick={()=>pick('essential')}>Essential only</button><button className="accept" onClick={()=>pick('accepted')}>Accept all</button></div>}
